{
  "technical_and_design_decisions": [
    "Implement ZK metadata isolation via tenant-specific path prefixes rather than separate ZK instances to minimize operational overhead",
    "Store Admin server credentials in transient in-memory storage only with no disk persistence, and use password-type input fields to prevent accidental logging",
    "Name the maintenance branch following semantic versioning (e.g., `maintenance/1.0.x`) and restrict it to minor/patch releases, with master reserved for major releases",
    "Prioritize cleanup of public-facing deprecated APIs first, with internal deprecated code removed entirely, and document all removals in release notes",
    "Use ZK as the primary source for xd-shell to fetch the dynamic admin server port, with a load balancer fallback only for restricted HDFS HA/federation setups as noted in the specification",
    "Limit the Kafka 0.9 consumer rewrite upgrade to dependency version updates and fixes only for failing core message bus tests to minimize regression risk",
    "Implement Motion-JPEG stream ingestion using Spring Integration HTTP inbound adapters, with OpenCV face detection wrapped in a platform-agnostic adapter layer to isolate native library dependencies",
    "Leverage Spring Boot's existing configuration property binding for the `messageRatesEnabled` parameter to avoid custom configuration loading logic"
  ],
  "assumptions": [
    "The existing codebase already has functional implementations of ZK metadata storage, Admin server, xd-shell, Kafka message bus, cluster view, and servers.yml configuration loading, so all work is incremental modification rather than greenfield development",
    "The Kafka 0.9 consumer rewrite is compatible with the existing Spring Kafka integration layer used in the project, requiring only dependency version updates and test fixes for the increment",
    "OpenCV platform compatibility issues can be resolved via a wrapper adapter that abstracts native library calls, eliminating the need for full platform-specific native builds for the initial increment",
    "The project's existing CI/CD pipeline supports branch protection rules and automated test execution for the maintenance branch workflow",
    "ZK access is available for xd-shell in standard deployment scenarios, with the load balancer fallback only required for the restricted HDFS setups explicitly noted in the U5 specification",
    "All user stories are independent and can be implemented without cross-story dependencies, allowing for sequential development by a single developer",
    "The existing test suite covers all core functionality affected by the changes in U1, U2, U4, U5, U6, U7, and U8, so regression testing only requires running the existing suite rather than creating new tests for unaffected functionality",
    "The project uses Spring Boot, so configuration parameter binding for U8 can leverage existing Spring Boot configuration infrastructure without custom implementation"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1: Implement ZK Tenant Namespace Isolation",
      "activity_description": "Design and implement per-tenant ZK namespace prefixing for all metadata operations, update existing ZK access code to use tenant-scoped paths, and add unit/integration tests to validate isolation between tenant profiles",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A2",
      "activity_name": "U2: Implement Admin Server Form-Based Authentication",
      "activity_description": "Integrate Spring Security to add a login form for the Admin server, implement transient in-memory credential storage (no file persistence) to avoid password logging, and add tests to verify authentication flow and that credentials are not persisted to disk",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A3",
      "activity_name": "U3: Set Up Git Maintenance Branch Workflow",
      "activity_description": "Create the maintenance branch for minor releases, configure CI/CD pipeline rules to allow minor release commits only to the maintenance branch, add merge checks to prevent direct commits to master for minor changes, and document the branch workflow for the team",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "U4: Clean Up Deprecated Functions",
      "activity_description": "Run static code analysis to identify all deprecated functions (including module definition download, Shell, and Admin-UI deprecated APIs), remove or replace deprecated code, add deprecation warnings for any public APIs scheduled for removal, and run full regression tests to verify no functionality is broken",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "U5 Spike: Research xd-shell Admin Server Port Access Approach",
      "activity_description": "Conduct spike to evaluate connecting xd-shell directly to ZK vs using a load balancer for admin server access, test ZK directory pointer approach for user experimentation, and document findings to inform the U5 implementation",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: Implement xd-shell Admin Server Port Access",
      "activity_description": "Implement ZK integration in xd-shell to fetch the dynamically assigned Tomcat admin server port, add a user-friendly command in xd-shell to retrieve and display the admin server address, implement the LB fallback logic for restricted ZK access scenarios per spike findings, and add tests for port retrieval and fallback behavior",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A7",
      "activity_name": "U6: Fix Failing Tests After Kafka 0.9 Consumer Rewrite Upgrade",
      "activity_description": "Upgrade the Kafka client dependency to the 0.9 consumer rewrite version, run the full existing test suite, identify and fix all failing tests related to message consumption, bus integration, and consumer group management, and update test configurations to align with the new consumer API",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "U7 Spike: Research Motion-JPEG Feasibility and Design Specs",
      "activity_description": "Conduct spike to evaluate Motion-JPEG format compatibility with the existing streaming pipeline, research OpenCV platform compatibility workarounds, and draft design specifications for the Motion-JPEG ingestion feature",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "U7: Implement Motion-JPEG Stream Ingestion Support",
      "activity_description": "Implement Motion-JPEG stream ingestion endpoints using Spring Integration, create a platform-agnostic OpenCV adapter wrapper to handle cross-platform compatibility issues, add unit tests for stream parsing and face detection pipeline integration, and document the new stream ingestion feature",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A10",
      "activity_name": "U8: Add Cluster View Message Rate Config Parameter",
      "activity_description": "Add the `messageRatesEnabled` configuration parameter to `servers.yml` with a default value of `true`, modify the cluster view component to read this configuration flag, update the Admin UI to conditionally render message rate metrics based on the flag, and add tests to verify the config toggle works as expected",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 112
  }
}

